/**
 * Web Mercator in the same pixel space as worldData.ts (generated by scripts/map.mjs).
 * Kept free of d3 so the runtime only ships these few lines.
 */
export const MAP_W = 3072
const R = MAP_W / (2 * Math.PI)
/** Must match MAP_Y_TOP in worldData.ts (latitude clipped at ±80°). */
export const MAP_Y_TOP = 344.861
export const MAP_H = 2382

export interface LatLng {
  lat: number
  lng: number
}

export function project({ lat, lng }: LatLng) {
  const phi = (lat * Math.PI) / 180
  return {
    x: ((lng + 180) / 360) * MAP_W,
    y: MAP_W / 2 - R * Math.log(Math.tan(Math.PI / 4 + phi / 2)) - MAP_Y_TOP,
  }
}

export function unproject(x: number, y: number): LatLng {
  const lng = (x / MAP_W) * 360 - 180
  const lat = (2 * Math.atan(Math.exp((MAP_W / 2 - (y + MAP_Y_TOP)) / R)) - Math.PI / 2) * (180 / Math.PI)
  return { lat, lng }
}

/** Great-circle distance in km (haversine, mean Earth radius). */
export function distanceKm(a: LatLng, b: LatLng) {
  const r = Math.PI / 180
  const dLat = (b.lat - a.lat) * r
  const dLng = (b.lng - a.lng) * r
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(dLng / 2) ** 2
  return 2 * 6371.0088 * Math.asin(Math.sqrt(h))
}
